/bin/bash -lc "python - <<'PY'
import bioblend.galaxy, json
key=open('/run/secrets/galaxy_api_key').read().strip()
gi=bioblend.galaxy.GalaxyInstance(url='https://usegalaxy.org', key=key)
url=gi.base_url + '/api/tools/toolshed.g2.bx.psu.edu/repos/goeckslab/phykit_metrics/phykit_metrics/0.2.0+galaxy0?io_details=true'
r=gi.make_get_request(url).json()

def walk(inputs, prefix=''):
    for inp in inputs:
        p=prefix+inp['name']
        if inp.get('type')=='conditional':
            print('\\nCOND', p)
            for case in inp.get('cases',[]):
                print(' CASE', case.get('value'))
                walk(case.get('inputs',[]), p+'|')
        elif inp.get('type')=='repeat':
            print('\\nREPEAT', p, 'min', inp.get('min'), 'max', inp.get('max'))
            walk(inp.get('inputs',[]), p+'|')
        else:
            print(f\"  {p} type={inp.get('type')} label={inp.get('label')} opt={inp.get('optional')} value={inp.get('value')} help={inp.get('help')}\")

for top in r['inputs']:
    if top['name']=='operation':
        for case in top.get('cases',[]):
            if case.get('value')=='relative_composition_variability':
                print('=== relative_composition_variability ===')
                walk(case.get('inputs',[]), 'operation|')
                # find grouped_zip and print full input JSON
                for m in case.get('inputs',[]):
                    if m['name']=='input_mode':
                        for c in m.get('cases',[]):
                            if c.get('value')=='grouped_zip_archives':
                                print('\\nGROUPED ZIP FULL JSON:')
                                print(json.dumps(c, indent=2))
PY"

